package service

import (
	"context"
	"fmt"
	"regexp"
	"strings"

	"github.com/google/uuid"
	"github.com/inboxes/backend/internal/store"
)

// Only image URLs generated by the composer are eligible for inline MIME
// conversion. The stored HTML keeps these authenticated URLs for previews.
var composerImageTag = regexp.MustCompile(`(?i)<img\b[^>]*\bsrc\s*=\s*["'](/api/attachments/([0-9a-f-]{36})/inline)["'][^>]*>`)

var inlineImageTypes = map[string]bool{
	"image/png": true, "image/jpeg": true, "image/gif": true, "image/webp": true,
}

// PrepareEmailAttachments converts composer images to CID references while
// keeping regular files as ordinary attachments. It also supports images in
// forwarded HTML, where the source IDs may be absent from attachmentIDs.
func PrepareEmailAttachments(ctx context.Context, st store.EmailStore, orgID, bodyHTML string, attachmentIDs []string) (string, []map[string]string, error) {
	inlineIDs := map[string]bool{}
	for _, match := range composerImageTag.FindAllStringSubmatch(bodyHTML, -1) {
		id, err := uuid.Parse(match[2])
		if err != nil {
			return "", nil, fmt.Errorf("invalid inline image reference")
		}
		inlineIDs[id.String()] = true
	}

	ids := make([]string, 0, len(attachmentIDs)+len(inlineIDs))
	seen := map[string]bool{}
	for _, id := range attachmentIDs {
		if !seen[id] {
			ids = append(ids, id)
			seen[id] = true
		}
	}
	for id := range inlineIDs {
		if !seen[id] {
			ids = append(ids, id)
			seen[id] = true
		}
	}
	if len(ids) == 0 {
		return bodyHTML, nil, nil
	}

	loaded, err := st.LoadAttachmentsForResend(ctx, ids, orgID)
	if err != nil {
		return "", nil, err
	}
	byID := make(map[string]map[string]string, len(loaded))
	for _, item := range loaded {
		byID[item["id"]] = item
	}
	for _, id := range ids {
		if byID[id] == nil {
			return "", nil, fmt.Errorf("attachment %s is unavailable", id)
		}
	}

	attachments := make([]map[string]string, 0, len(ids))
	for _, id := range ids {
		item := byID[id]
		payload := map[string]string{
			"content": item["content"], "filename": item["filename"],
		}
		if inlineIDs[id] {
			if !inlineImageTypes[item["content_type"]] {
				return "", nil, fmt.Errorf("attachment %s is not a supported image", id)
			}
			payload["content_type"] = item["content_type"]
			payload["content_id"] = "inboxes-image-" + id
		}
		attachments = append(attachments, payload)
	}

	sendHTML := composerImageTag.ReplaceAllStringFunc(bodyHTML, func(tag string) string {
		match := composerImageTag.FindStringSubmatch(tag)
		id, _ := uuid.Parse(match[2])
		return strings.Replace(tag, match[1], "cid:inboxes-image-"+id.String(), 1)
	})
	return sendHTML, attachments, nil
}
